const categories=['Alle aktiviteter','Lek & fellesskap','Sang & musikk','Ut på tur','Kafé & kos'];let active='Alle aktiviteter',onlySaved=false;let favorites;try{favorites=new Set(JSON.parse(localStorage.getItem('permliv-favorites')||'[]'))}catch{favorites=new Set()}
const art=(scene,bg)=>{const drawings={play:'<rect x="90" y="105" width="45" height="45" rx="4" fill="#af8264"/><rect x="139" y="123" width="38" height="28" rx="3" fill="#829377"/><path d="M95 100l18-31 19 31" fill="#d4a776"/><circle cx="227" cy="108" r="32" fill="#9eae89"/><path d="M204 108h46M227 77v62" stroke="#e2e6cf" stroke-width="2"/><path d="M188 149q60 17 94-2" stroke="#c1ae91" fill="none" stroke-width="5"/>',music:'<path d="M155 110V54l60-12v57" fill="none" stroke="#7a8066" stroke-width="7"/><ellipse cx="142" cy="113" rx="17" ry="12" fill="#7a8066"/><ellipse cx="202" cy="101" rx="17" ry="12" fill="#7a8066"/><circle cx="259" cy="126" r="27" fill="#c39171"/><circle cx="259" cy="126" r="20" fill="#e0bb8e"/><path d="M95 72l5-13m-15 5 15 5" stroke="#b39263" stroke-width="3"/>',forest:'<path d="M0 160Q100 100 180 143T360 115V180H0" fill="#afbf9d"/><path d="M125 180q80-50 118-37t-9-33" stroke="#eadfc6" stroke-width="22" fill="none"/><g fill="#6f8a6a"><path d="M50 142V62h5v80zM40 112l13-68 18 68zM278 133V50h5v83zM259 107l22-77 24 77z"/></g><circle cx="111" cy="48" r="18" fill="#f3e9cb"/>',coffee:'<ellipse cx="180" cy="149" rx="77" ry="9" fill="#d0c3a8"/><path d="M137 77h76v34q0 33-38 33t-38-33z" fill="#f9f5e9"/><path d="M214 82q36-1 23 27-8 10-23 7" stroke="#f9f5e9" stroke-width="9" fill="none"/><path d="M163 59q-11-12 0-25m22 25q-11-12 0-25" stroke="#aeaa8e" stroke-width="3" fill="none"/><ellipse cx="175" cy="78" rx="38" ry="8" fill="#8e7258"/>',sea:'<path d="M0 110q90-20 180 0t180 0v70H0" fill="#a3beb7"/><path d="M0 145q90-20 180 0t180 0" stroke="#cbdcd1" stroke-width="3" fill="none"/><path d="M150 111h80l-17 22h-48z" fill="#6c8577"/><path d="M185 107V38l-33 63z" fill="#fff8e7"/><path d="M190 101V48l36 53z" fill="#c4ab85"/><circle cx="282" cy="40" r="21" fill="#e9d3a0"/>'};return `<svg viewBox="0 0 360 180" aria-hidden="true"><rect width="360" height="180" fill="${bg}"/>${drawings[scene]}</svg>`};
function render(){document.querySelector('.filters').innerHTML=categories.map(c=>`<button class="filter ${active===c?'active':''}" aria-pressed="${active===c}" data-category="${c}">${c}</button>`).join('');const query=document.querySelector('#search').value.toLocaleLowerCase('nb');const shown=activities.filter(a=>(active==='Alle aktiviteter'||a.category===active)&&(!onlySaved||favorites.has(a.id))&&`${a.title} ${a.description} ${a.place} ${a.category}`.toLocaleLowerCase('nb').includes(query));document.querySelector('#count').textContent=`${shown.length} ${onlySaved?'favoritter':'aktiviteter og ideer'} · Haugesund`;document.querySelector('#saved-count').textContent=favorites.size;document.querySelector('#saved').setAttribute('aria-pressed',onlySaved);document.querySelector('#saved').style.background=onlySaved?'#e4eadb':'';document.querySelector('#grid').innerHTML=shown.map(a=>`<article class="card"><div class="picture">${art(a.scene,a.bg)}<span class="badge">${a.badge}</span><button class="heart" data-save="${a.id}" aria-label="${favorites.has(a.id)?'Fjern':'Lagre'} ${a.title} ${favorites.has(a.id)?'fra':'som'} favoritt" aria-pressed="${favorites.has(a.id)}">${favorites.has(a.id)?'♥':'♡'}</button></div><div class="body"><div class="category">${a.category}</div><h3>${a.title}</h3><p class="description">${a.description}</p><div class="meta">⌖ ${a.place}<br>◷ ${a.time}</div><div class="card-bottom"><span class="kind">${a.kind}</span><a href="${a.url}" target="_blank" rel="noopener">${a.link} ↗</a></div></div></article>`).join('')||'<div class="empty">Ingen treff akkurat nå. Prøv en annen kategori eller et annet søk.</div>'}
document.querySelector('.filters').addEventListener('click',e=>{if(e.target.dataset.category){active=e.target.dataset.category;render()}});document.querySelector('#search').addEventListener('input',render);document.querySelector('#saved').addEventListener('click',()=>{onlySaved=!onlySaved;render();document.querySelector('#aktiviteter').scrollIntoView({behavior:'smooth'})});document.querySelector('#grid').addEventListener('click',e=>{const b=e.target.closest('[data-save]');if(!b)return;favorites.has(b.dataset.save)?favorites.delete(b.dataset.save):favorites.add(b.dataset.save);try{localStorage.setItem('permliv-favorites',JSON.stringify([...favorites]))}catch{}render()});render();
